def max_segments(n, k, a):
    def flip(x):
        return x ^ ((1 << k) - 1)

    def count_non_zero_xor_segments(arr):
        count = 0
        current_xor = 0
        for num in arr:
            current_xor ^= num
            if current_xor != 0:
                count += 1
        return count

    max_segments = 0
    for i in range(n):
        flipped_arr = [flip(a[j]) if j == i else a[j] for j in range(n)]
        max_segments = max(max_segments, count_non_zero_xor_segments(flipped_arr))

    return max_segments

