def max_segments(n, k, a):
    result = 0
    current_segment_has_one = False

    for num in a:
        if num != 0:
            if not current_segment_has_one:
                result += 1
                current_segment_has_one = True
        else:
            current_segment_has_one = False

    return result + 1

